import type { HTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// A short label for a state or a kind (console2.css .c-badge under the console): 18px, square, 11px lowercase words.
// default: a hairline in ink; working: black, for a source at work; failed: the red wash with a red square; quiet: a
// hairline in the muted grey, for a note such as "default" or "invited". The word carries the state, never colour alone.
export interface TagProps extends HTMLAttributes<HTMLSpanElement> {
  tone?: 'default' | 'working' | 'failed' | 'quiet'
  /** What leads the word (Vue's `mark` slot); by default a red square on `failed`. */
  mark?: ReactNode
  'data-ds'?: string
}

const TONES = {
  default: 'border-edge text-fg',
  working: 'border-status-working bg-status-working text-status-working-fg',
  failed: 'border-transparent bg-status-failed text-status-failed-fg',
  quiet: 'border-edge text-fg-muted',
}

export function Tag({ tone = 'default', mark, className, children, ...rest }: TagProps) {
  return (
    <span data-ds="tag" className={cn('inline-flex h-4.5 items-center gap-1 border px-1.25 pb-0.5 text-caption leading-4 font-normal whitespace-nowrap', TONES[tone], className)} {...rest}>
      {mark ?? (tone === 'failed' && <span className="mt-0.5 size-1 shrink-0 bg-edge-accent" aria-hidden="true" />)}
      {children}
    </span>
  )
}

export default Tag

import { DotMatrix } from '@/react/components/ui/DotMatrix'
import { Tag } from '@/react/components/ui/Tag'

// A source's state as a tag (the console's Status.vue): ready in a hairline, syncing and connecting in black with the
// dot matrix at work, error in the red wash with its square. Red marks only a failure.
export interface StatusTagProps {
  status: 'ready' | 'syncing' | 'connecting' | 'error' | (string & {})
  className?: string
}

export function StatusTag({ status, className }: StatusTagProps) {
  const working = status === 'syncing' || status === 'connecting'
  const tone = status === 'error' ? 'failed' : working ? 'working' : 'default'
  return (
    <Tag data-ds="status-tag" tone={tone} className={className} mark={working ? <DotMatrix tone="inverse" className="mt-0.5 mr-0.5" /> : undefined}>
      {status}
    </Tag>
  )
}

export default StatusTag

import type { HTMLAttributes } from 'react'
import { cn } from '@/react/lib/cn'

// The website's tag (Tag.vue on conare.ai): 10px capitals on the red, tracked 0.06em, the system's only capitals.
// `framed` adds a second rule 2px outside, as the cards' double rule (the hero's eyebrow).
export interface SiteTagProps extends HTMLAttributes<HTMLSpanElement> {
  framed?: boolean
}

export function SiteTag({ framed, className, children, ...rest }: SiteTagProps) {
  return (
    <span
      data-ds="site-tag"
      className={cn('inline-block bg-home-red py-0.75 pr-[calc(4px-0.06em)] pl-1 type-tag text-off-white [text-box:trim-both_cap_alphabetic]', framed && 'outline outline-offset-2 outline-home-red', className)}
      {...rest}
    >{children}</span>
  )
}

export default SiteTag

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

