import { html, nothing, type TemplateResult } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Tag.vue as <conare-tag>: a short label for a state or a kind (console2.css .c-badge under the console): 18px,
// square, 11px lowercase words. default: a hairline in ink; working: black, for a source at work; failed: the red wash
// with a red square; quiet: a hairline in the muted grey, for a note such as "default" or "invited". The word carries
// the state, never colour alone.
export type TagTone = 'default' | 'working' | 'failed' | 'quiet'
const TONES: Record<TagTone, string> = {
	default: 'border-edge text-fg',
	working: 'border-status-working bg-status-working text-status-working-fg',
	failed: 'border-transparent bg-status-failed text-status-failed-fg',
	quiet: 'border-edge text-fg-muted',
}

/**
 * @summary A short label for a state or a kind.
 * @slot - The word.
 * @slot mark - What leads the word; by default a red square on `failed`.
 */
export class Tag extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { tone: {} }

	tone: TagTone = 'default'

	/** What leads the word: the `mark` slot, a red square on `failed` by default. */
	protected renderMark(): TemplateResult | typeof nothing {
		return html`<slot name="mark">${this.tone === 'failed' ? html`<span class="mt-0.5 size-1 shrink-0 bg-edge-accent" aria-hidden="true"></span>` : nothing}</slot>`
	}
	/** The word. */
	protected renderLabel(): TemplateResult | string {
		return html`<slot></slot>`
	}

	render() {
		const name = (this.constructor as typeof DsElement).dsName
		return html`<span data-ds="${name}" class=${['inline-flex h-4.5 items-center gap-1 border px-1.25 pb-0.5 text-caption leading-4 font-normal whitespace-nowrap', TONES[this.tone] ?? TONES.default].join(' ')}>${this.renderMark()}${this.renderLabel()}</span>`
	}
}

define('tag', Tag)

import { html, nothing, type PropertyValues } from 'lit'
import { html as staticHtml } from 'lit/static-html.js'
import { define, tag } from '@/elements/lib/element'
import { Tag } from '@/elements/components/ui/tag'
import '@/elements/components/ui/dot-matrix'
import styles from 'virtual:tw'

// StatusTag.vue as <conare-status-tag>: a source's state as a tag (the console's Status.vue): ready in a hairline,
// syncing and connecting in black with the dot matrix at work, error in the red wash with its square. Red marks only a
// failure. It is a <conare-tag> whose tone and word come from `status`.

/**
 * @summary A source's state as a tag.
 */
export class StatusTag extends Tag {
	static styles = [Tag.styles, styles]
	static properties = { ...Tag.properties, status: {} }

	/** ready, syncing, connecting or error (any other word shows as it is, in a hairline). */
	status = ''

	get working() {
		return this.status === 'syncing' || this.status === 'connecting'
	}

	protected willUpdate(changed: PropertyValues) {
		super.willUpdate(changed)
		this.tone = this.status === 'error' ? 'failed' : this.working ? 'working' : 'default'
	}

	protected renderMark() {
		if (this.working) return staticHtml`<${tag('dot-matrix')} tone="inverse" class="mt-0.5 mr-0.5"></${tag('dot-matrix')}>`
		return this.tone === 'failed' ? html`<span class="mt-0.5 size-1 shrink-0 bg-edge-accent" aria-hidden="true"></span>` : nothing
	}
	protected renderLabel() {
		return this.status
	}
}

define('status-tag', StatusTag)

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// SiteTag.vue as <conare-site-tag>: the website's tag (Tag.vue on conare.ai): 10px capitals on the red, tracked
// 0.06em, the system's only capitals. `framed` adds a second rule 2px outside, as the cards' double rule (the hero's
// eyebrow).

/**
 * @summary The website's tag: small capitals on the red.
 * @slot - The word.
 */
export class SiteTag extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { framed: { type: Boolean } }

	/** A second rule 2px outside. */
	framed = false

	render() {
		return html`<span data-ds="site-tag" class=${['inline-block bg-home-red py-0.75 pr-[calc(4px-0.06em)] pl-1 type-tag text-off-white [text-box:trim-both_cap_alphabetic]', this.framed ? 'outline outline-offset-2 outline-home-red' : ''].join(' ')}><slot></slot></span>`
	}
}

define('site-tag', SiteTag)
